/*
<Group description="Fundo e Cores Base" selector="body">
  <Variable name="body.background" description="Fundo Geral" type="background" color="#f9fafb" default="$(color) none repeat scroll top left" value="$(color) none repeat scroll top left"/>
  <Variable name="main.color" description="Cor Principal" type="color" default="#2563eb" value="#2563eb"/>
  <Variable name="theme.text" description="Cor do Texto" type="color" default="#374151" value="#374151"/>
  <Variable name="header.bg" description="Fundo do Cabeçalho" type="color" default="#ffffff" value="#ffffff"/>
  <Variable name="footer.bg" description="Fundo do Rodapé" type="color" default="#111827" value="#111827"/>
</Group>
<Group description="Tipografia" selector="body">
  <Variable name="body.font" description="Fonte do Texto" type="font" default="normal normal 16px system-ui,-apple-system,sans-serif" value="normal normal 16px system-ui,-apple-system,sans-serif"/>
</Group>
*/

:root {
  --sl-bg-body:        $(body.background);
  --sl-text-main:      $(theme.text);
  --sl-primary:        $(main.color);
  --sl-card-bg:        #ffffff;
  --sl-footer-bg:      #111827;
  --sl-nav-bg:         #ffffff;
  --sl-radius-lg:      12px;
  --sl-radius-sm:      6px;
  --sl-transition:     all 0.3s cubic-bezier(0.4,0,0.2,1);
  --sl-btn-radius:     8px;
  --sl-btn-shadow:     0 2px 6px rgba(0,0,0,0.15);
  --sl-font-family:    system-ui,-apple-system,sans-serif;
  --sl-heading-weight: 700;
}

[[DYNAMIC_CSS]]

body {
  background-color: var(--sl-bg-body,#f9fafb);
  color: var(--sl-text-main);
  font-family: var(--sl-font-family,system-ui,sans-serif);
  margin:0; padding:0; overflow-x:hidden;
  -webkit-font-smoothing:antialiased;
}
img { max-width:100%; height:auto; display:block; }
a { color:var(--sl-primary); text-decoration:none; transition:var(--sl-transition); }
a:hover { filter:brightness(0.85); }
h1,h2,h3,h4,h5,h6 { font-weight:var(--sl-heading-weight); }

/* ── HEADER / NAV ──────────────────────────────────────── */
/* .header-logo (wrapper estático real) + .sl-header-brand (classe real
   do [[HEADER_WIDGET]] genérico, gerarHeaderWidget() em widgets.js —
   não é .mag-header-content/.mag-logo-link, isso nunca existiu na
   saída real deste token). */
.header-logo { padding-top: 1.25rem; padding-bottom: 1.25rem; text-align: center; }
.sl-header-brand { font-size: clamp(1.6rem, 4vw, 2.2rem); font-weight: 900; letter-spacing: -.5px; text-transform: uppercase; }
.navbar-container { border-top: 1px solid var(--mag-border,rgba(0,0,0,.08)); border-bottom: 4px solid var(--mag-dark,var(--sl-text-main)); background-color: var(--sl-card-bg); }
[data-bs-theme="dark"] .navbar-container { border-bottom-color: var(--sl-primary); }
.navbar .nav-link { font-weight: 500; text-transform: uppercase; letter-spacing: 1px; font-size: 0.85rem; color: var(--sl-text-main) !important; padding: 15px 20px !important; }
.navbar .nav-link:hover { color: var(--sl-primary) !important; }

/* ── ANIMAÇÃO DE ENTRADA (real: .animate-up, usada no feed e no post) ── */
.animate-up { opacity: 0; transform: translateY(20px); transition: 0.8s cubic-bezier(0.16, 1, 0.3, 1); }
.animate-up.visible { opacity: 1; transform: translateY(0); }

/* ── FEED (marcação real: .news-card, sem grid/post-destacado) ───── */
.news-card { background: transparent; border: none; transition: transform 0.3s; height: 100%; }
.news-card-img { overflow: hidden; border-radius: var(--sl-radius-lg); background: color-mix(in srgb, var(--sl-text-main) 6%, transparent); }
.news-card-img img { transition: transform 0.5s ease; }
.news-card:hover .news-card-img img { transform: scale(1.05); }
.news-title a { color: var(--sl-text-main); }
.news-card:hover .news-title a { color: var(--sl-primary); filter:none; }
.widget-title { font-weight: 900; font-size: 1.5rem; border-bottom: 2px solid var(--sl-primary); padding-bottom: 10px; margin-bottom: 20px; }

/* ── POST ÚNICO (marcação real: .post-header-single/.post-title-single/
     .post-body-content — NUNCA .post-body, essa classe nunca existiu
     no arquivo real) ────────────────────────────────────────────── */
.post-header-single { text-align: center; margin-bottom: 3rem; padding-bottom: 2rem; border-bottom: 1px solid rgba(0,0,0,.08); }
.post-title-single { font-weight: 900; font-size: clamp(2.2rem, 5vw, 3.5rem); line-height: 1.15; margin: 15px 0; }
.post-body-content { font-size: 1.1rem; line-height: 1.8; }
.post-body-content img, .post-body-content iframe { max-width: 100% !important; height: auto !important; margin: 2rem 0; border-radius: var(--sl-radius-sm); }
.post-body-content > p:first-of-type::first-letter, .post-body-content > div:first-of-type::first-letter { font-size: 4rem; font-weight: 900; float: left; line-height: .8; margin-right: 12px; margin-top: 5px; color: var(--sl-primary); }

/* ── 404 (embutido no main/post real, data:view.isError) ─────────── */
.error-404-wrapper { min-height: 50vh; display: flex; flex-direction: column; justify-content: center; align-items: center; text-align: center; padding: 4rem 1rem; }
.error-code { font-size: clamp(4rem, 15vw, 8rem); font-weight: 900; line-height: 1; color: var(--sl-primary); }

/* ── BUTTONS ──────────────────────────────────────────── */
.btn-primary,.btn-outline-primary { border-radius:var(--sl-btn-radius); box-shadow:var(--sl-btn-shadow); }
.btn-outline-primary { color:var(--sl-primary); border-color:var(--sl-primary); }
.btn-outline-primary:hover,.btn-outline-primary:focus,.btn-outline-primary:active,.btn-outline-primary.active {
  background-color:var(--sl-primary); border-color:var(--sl-primary); color:#fff; filter:none;
}

/* ── FOOTER (marcação real: .mag-footer, NUNCA .sl-footer) ────────── */
.mag-footer { background:var(--sl-footer-bg,#111827); color:#94a3b8; padding-top: 4rem; margin-top: 4rem; }
.mag-footer h6,.mag-footer .title { color:#f1f5f9; font-weight:700; text-transform:uppercase; letter-spacing:.06em; font-size:.75rem; margin-bottom:1rem; }
.mag-footer a { color:#94a3b8; font-size:.875rem; }
.mag-footer a:hover { color:#f1f5f9; filter:none; }
.mag-footer-divider { border-color:rgba(255,255,255,0.08) !important; }

/* ── DARK MODE ────────────────────────────────────────── */
[data-bs-theme="dark"] body { background-color:#0f172a; color:#cbd5e1; }
[data-bs-theme="dark"] .navbar-container { background:#1e293b !important; }
[data-bs-theme="dark"] .post-header-single { border-color: rgba(255,255,255,.08); }

/* GRID LAYOUTS (lista/dupla/revista/quadrado/mural/coluna-unica/zigzag) —
   centralizado em gerarGridCardCss() (designTokensCss.js), injetado via
   DYNAMIC_CSS. O feed real (row-cols-md-2, g-5, sem post-destacado) não
   usa nenhuma dessas classes — gridLayout mantido em
   nichoModuleDefaults.js mas sem efeito visual aqui, mesmo trade-off já
   documentado em viral-magazine/appstore-bulma-mobile. */

/* === CSS DO NICHO ===================================== */
