                //
                document.addEventListener('DOMContentLoaded', () => {
                  const label = '';
                  const cUrl = '';
                  const rGrid = document.getElementById('related-grid');

                  fetch('/feeds/posts/default/-/' + label + '?alt=json-in-script&max-results=4')
                  .then(res => res.text())
                  .then(txt => {
                    const jsonStr = txt.replace('gdata.io.handleScriptLoaded(', '').slice(0, -2);
                    const d = JSON.parse(jsonStr);
                    rGrid.innerHTML = '';
                    const feed = d.feed;
                    if (!feed.entry || feed.entry.length === 0) { rGrid.innerHTML = '<div class="col-12 text-muted">Nenhuma edição encontrada.</div>'; return; }
                    let c = 0;
                    feed.entry.forEach(e => {
                      if (c >= 3) return;
                      let pUrl = ''; e.link.forEach(l => { if (l.rel === 'alternate') pUrl = l.href; });
                      if (pUrl.split('?')[0] === cUrl) return;
                      let pImg = e.media$thumbnail ? e.media$thumbnail.url.replace(/\/s\d+(\-c)?\//, '/w600-h450-p/') : '[[PLACEHOLDER_IMG]]';
                      const title = e.title.$t;
                      rGrid.innerHTML += `
                        <div class="col-md-4">
                          <div class="news-card">
                            <a href="${pUrl}">
                              <div class="news-card-img ratio ratio-4x3 mb-3"><img src="${pImg}" class="rounded-3 object-fit-cover" alt="Thumb"></div>
                              <h6 class="fw-bold" style="font-size: 1.1rem;">${title}</h6>
                            </a>
                          </div>
                        </div>
                      `;
                      c++;
                    });
                  });

                  const textBlock = document.getElementById('post-body-content').innerText;
                  const words = textBlock.trim().split(/\s+/).length;
                  const time = Math.ceil(words / 225);
                  document.getElementById('read-time-calc').innerHTML = `<i class='bi bi-book me-1'></i> ${time} min de leitura`;
                });
                //





















